const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries
  const cumbreaVieja = ee.Geometry.Point([-17.84, 28.0]);
  const funchalIsland = ee.Geometry.Point([-17.0, 32.76]);

  // 2. Date range
  const date = '2021-10-18';
  const startDate = '2021-10-18';
  const endDate = '2021-10-19';

  // 3. Load Sentinel-5P SO2 data
  const so2Collection = ee.ImageCollection('COPERNICUS/S5P/NRTI_SO2')
    .filterDate(startDate, endDate);

  const collectionSize = so2Collection.size().getInfo();
  console.log(`S5P SO2 Images (Oct 18, 2021): ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No S5P SO2 data available for October 18, 2021.');
    console.log('C1');
    return;
  }

  // 4. Get the first image (NRTI should have daily coverage)
  const so2Image = so2Collection.first().select('SO2_column_number_density');

  // 5. Extract SO2 values at Cumbre Vieja
  const so2CumbreaStats = so2Image.sample(cumbreaVieja, 10000).first().getInfo();
  const so2Cumbrea = so2CumbreaStats ? so2CumbreaStats.properties.SO2_column_number_density : null;

  // 6. Extract SO2 values at Funchal Island
  const so2FunchalStats = so2Image.sample(funchalIsland, 10000).first().getInfo();
  const so2Funchal = so2FunchalStats ? so2FunchalStats.properties.SO2_column_number_density : null;

  console.log(`Cumbre Vieja SO2: ${so2Cumbrea !== null ? so2Cumbrea.toFixed(4) : 'null'} mol/m²`);
  console.log(`Funchal Island SO2: ${so2Funchal !== null ? so2Funchal.toFixed(4) : 'null'} mol/m²`);

  // 7. Validation
  if (so2Cumbrea === null || so2Funchal === null || isNaN(so2Cumbrea) || isNaN(so2Funchal)) {
    console.log('Invalid or missing SO2 values.');
    console.log('C3');
    return;
  }

  if (so2Cumbrea < 0 || so2Funchal < 0) {
    console.log('Negative SO2 values detected (invalid).');
    console.log('C3');
    return;
  }

  // 8. Comparison
  const difference = so2Cumbrea - so2Funchal;
  console.log(`Difference (Cumbre Vieja - Funchal): ${difference.toFixed(4)} mol/m²`);

  if (so2Cumbrea > so2Funchal) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
